import pandas as pd, statsmodels.formula.api as smf
x=pd.read_csv('data/explore.csv');
for v in x.columns[2:-1]:
 d=x[['species_richness','region',v]].dropna(); m=smf.ols(f'species_richness ~ {v} + C(region)',d).fit(); print(v, round(m.params[v],3),round(m.pvalues[v],5), round(m.rsquared,3))

